using Astrea;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo;

public abstract class StatisticsData : ScriptableObject
{
	[Header("Debug")]
	[SerializeField]
	protected Character debugCharacter;

	[Header("Datas")]
	[SerializeField]
	protected SaveSystem saveSystem;

	[Header("Infos")]
	[SerializeField]
	protected string ID;

	[SerializeField]
	protected string key;

	[SerializeField]
	private bool enableCustomName;

	[SerializeField]
	[ShowIf("enableCustomName")]
	private StatisticsCustomName statisticsCustomName;

	[Header("Hidden")]
	[SerializeField]
	private bool enableAchievementDataHiddenHandler;

	[SerializeField]
	[ShowIf("enableAchievementDataHiddenHandler")]
	private AchievementDataHiddenHandler achievementDataHiddenHandler;

	[SerializeField]
	protected ColorReference colorTMP;

	protected string jsonValueSerialized;

	public bool EnableCustomName => enableCustomName;

	public string GetID()
	{
		return ID;
	}

	protected bool IsHidden()
	{
		if (enableAchievementDataHiddenHandler && achievementDataHiddenHandler.IsHidden())
		{
			return true;
		}
		return false;
	}

	public abstract string GetValue();

	protected abstract void SerializeValue();

	protected abstract void DeserializeValue();

	public virtual string GetCustomName()
	{
		if (IsHidden())
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedQuestionMarkSixTimes();
		}
		if (enableCustomName)
		{
			return statisticsCustomName.GetCustomName(this);
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(ID);
	}

	public Color GetColor()
	{
		return colorTMP.Value;
	}

	public void LoadStatisticsData(string characterName, bool debug = false)
	{
		if (!(key == ""))
		{
			Clear();
			jsonValueSerialized = "";
			if (saveSystem.HasStatistics(characterName + key + "Data"))
			{
				saveSystem.LoadStatistics(characterName + key + "Data", ref jsonValueSerialized, debug);
			}
			DeserializeValue();
		}
	}

	public void SaveStatisticsData(string characterName, bool debug = false)
	{
		if (!(key == ""))
		{
			SerializeValue();
			saveSystem.SaveStatistics(characterName + key + "Data", ref jsonValueSerialized, debug);
		}
	}

	public abstract void Clear();

	public void DeleteStatisticsData(string characterName)
	{
		if (saveSystem != null)
		{
			saveSystem.DeleteStatistics(characterName + key + "Data");
		}
	}
}
